function instPrompt(a){
  var doc;
  if(a.ext){doc=a.n+'(제작: Tangency Labs)의 공식 문서·저장소 주소는 아직 모릅니다. 먼저 ArtCraft 런처의 앱 정보 화면과 웹 검색으로 공식 문서 주소를 찾아서 알려줘.'}
  else if(a.agents){doc=a.n+' 문서 :\n'+a.agents}
  else{doc=a.n+' 저장소 :\n'+a.repo+'\n(저장소에 AGENTS.md가 있으면 가장 먼저 읽고, 없으면 README.md와 최신 릴리스 노트를 읽어줘.)'}
  var t=doc+'\n위 문서를 읽어보고 AI가 '+a.n+'를 사용해 직접 '+a.job+'하게 해주는 CLI랑 MCP 설치해 줘.\n';
  t+='정확히 내 컴퓨터 사양에 맞게 설치해야 해. 먼저 내 운영체제, CPU 구조(Apple silicon/Intel, x64/ARM64), 설치된 Rust 버전을 확인해줘'+(a.rust&&a.rust!=='-'?'(이 앱은 Rust '+a.rust+' 이상이 필요하다고 해).':'.')+'\n';
  t+='공식 페이지에는 CLI 내려받기가 macOS(Universal)용만 안내되어 있어. 내 컴퓨터가 다른 환경이면 소스 빌드 방법을 알려주고 이어서 진행해줘.\n';
  if(a.mcp==='N'||a.mcp==='U'){t+='MCP 서버가 공식 문서에 없다면 CLI만 설치하고, MCP가 없다는 사실을 알려줘.\n'}
  t+='가능하면 네가 직접 하고, 권한 문제상 내가 직접 해야 하는 부분이 있다면 어떻게 해야 하는지 정확히 안내해줘.\n설치가 끝나면 간단한 명령으로 CLI와 MCP가 정상 연결됐는지 확인한 결과도 알려줘.';
  return t;
}
